/**
 * Meta Configuration Diagnostic Script
 *
 * Checks:
 * 1. App status, basic settings, and Data Use Checkup status
 * 2. Login for Business Configuration (config_id) permissions and status
 * 3. App permissions and review levels (Standard vs Advanced Access)
 *
 * Usage:
 *   META_APP_ID=... META_APP_SECRET=... META_CONFIG_ID=... npx tsx scripts/verify-meta-config.ts
 */

const appId = process.env.META_APP_ID || process.env.NEXT_PUBLIC_META_APP_ID;
const appSecret = process.env.META_APP_SECRET;
const configId = process.env.META_CONFIG_ID || process.env.NEXT_PUBLIC_META_LOGIN_FOR_BUSINESS_CONFIG_ID;

const GRAPH_VERSION = 'v21.0';
const GRAPH_BASE = `https://graph.facebook.com/${GRAPH_VERSION}`;

async function runDiagnostic() {
  console.log('='.repeat(60));
  console.log('🔍 META OAUTH & APP CONFIGURATION DIAGNOSTIC');
  console.log('='.repeat(60));

  if (!appId) {
    console.error('❌ Missing META_APP_ID (or NEXT_PUBLIC_META_APP_ID).');
    process.exit(1);
  }

  console.log(`📱 Meta App ID: ${appId}`);
  if (configId) {
    console.log(`⚙️  Login for Business Config ID: ${configId}`);
  } else {
    console.log('⚠️  No Config ID provided.');
  }

  if (!appSecret) {
    console.log('\n⚠️  META_APP_SECRET was not provided in the environment.');
    console.log('   Running public/app-tokenless checks only...\n');
  }

  const appToken = appSecret ? `${appId}|${appSecret}` : null;

  // 1. Check App Details
  console.log('\n1️⃣ Checking Meta App Status & Basic Info...');
  try {
    const fields = [
      'id',
      'name',
      'link',
      'category',
      'app_domains',
      'privacy_policy_url',
      'terms_of_service_url',
      'user_support_email',
      'data_use_checkup',
      'restrictions',
      'supported_platforms',
    ].join(',');

    const url = appToken
      ? `${GRAPH_BASE}/${appId}?fields=${fields}&access_token=${appToken}`
      : `${GRAPH_BASE}/${appId}?fields=id,name`;

    const res = await fetch(url);
    const data = await res.json();

    if (data.error) {
      console.error(`❌ Meta API Error checking App: [${data.error.code}] ${data.error.message}`);
    } else {
      console.log(`✅ App Name: ${data.name}`);
      if (data.category) console.log(`   Category: ${data.category}`);
      if (data.app_domains) console.log(`   App Domains: ${JSON.stringify(data.app_domains)}`);
      if (data.privacy_policy_url) console.log(`   Privacy Policy: ${data.privacy_policy_url}`);
      if (data.terms_of_service_url) console.log(`   Terms of Service: ${data.terms_of_service_url}`);
      if (data.data_use_checkup) {
        console.log(`   Data Use Checkup: ${JSON.stringify(data.data_use_checkup)}`);
      }
      if (data.restrictions) {
        console.log(`   ⚠️ Restrictions: ${JSON.stringify(data.restrictions)}`);
      }
    }
  } catch (err) {
    console.error('❌ Failed to query Meta App info:', err);
  }

  // 2. Check Facebook Login for Business Configuration (config_id)
  if (configId && appToken) {
    console.log('\n2️⃣ Checking Facebook Login for Business Configuration ID...');
    try {
      const url = `${GRAPH_BASE}/${configId}?fields=id,name,business_id,permissions,response_type,session_duration,asset_types&access_token=${appToken}`;
      const res = await fetch(url);
      const data = await res.json();

      if (data.error) {
        console.error(`❌ Meta API Error on Config ID ${configId}:`);
        console.error(`   Code: ${data.error.code} | Subcode: ${data.error.error_subcode || 'N/A'}`);
        console.error(`   Message: ${data.error.message}`);
      } else {
        console.log(`✅ Configuration Found: "${data.name || data.id}"`);
        if (data.business_id) console.log(`   Owning Business ID: ${data.business_id}`);
        if (data.permissions) {
          console.log(`   Configured Permissions:`);
          data.permissions.forEach((p: any) => console.log(`     - ${p}`));
        }
        if (data.asset_types) {
          console.log(`   Configured Asset Types: ${JSON.stringify(data.asset_types)}`);
        }
      }
    } catch (err) {
      console.error('❌ Failed to query Config ID:', err);
    }
  }

  // 3. Check App Permissions & Review Status
  if (appToken) {
    console.log('\n3️⃣ Checking App Permissions & Access Levels (Standard vs Advanced)...');
    try {
      const url = `${GRAPH_BASE}/${appId}/permissions?access_token=${appToken}`;
      const res = await fetch(url);
      const data = await res.json();

      if (data.error) {
        console.error(`❌ Meta API Error on /permissions: [${data.error.code}] ${data.error.message}`);
      } else if (data.data) {
        console.log(`📋 Permissions & Review Status:`);
        const permissions: Array<{ permission: string; status: string }> = data.data;
        if (permissions.length === 0) {
          console.log('   (No explicit permissions returned on /permissions endpoint)');
        } else {
          permissions.forEach((p) => {
            const isAdvanced = p.status === 'live' || p.status === 'granted';
            const icon = isAdvanced ? '🟢' : '🟡';
            console.log(`   ${icon} ${p.permission}: ${p.status}`);
          });
        }
      }
    } catch (err) {
      console.error('❌ Failed to query App Permissions:', err);
    }
  }

  console.log('\n' + '='.repeat(60));
  console.log('🏁 DIAGNOSTIC COMPLETE');
  console.log('='.repeat(60));
}

runDiagnostic().catch(console.error);

